sys_ui_action.script:
// bfd_ui_close_case — attempt the transition to closed. The existing
// closure-guard business rule aborts the update and adds its own error message
// when mandatory tasks or resolution fields are incomplete, so this action
// re-reads the record afterwards and reports the outcome cleanly.
(function closeCaseAction() {
    var CASE_TABLE = 'x_1755386_safetr_0_bfd_fraud_dispute_case';
    var caseId = current.getUniqueValue();

    if (current.getValue('case_status') === 'closed') {
        gs.addInfoMessage('This case is already closed.');
        action.setRedirectURL(current);
        return;
    }

    current.setValue('case_status', 'closed');
    new bfd_TriageEngine().logAiDecision(current, {
        note: 'Closure requested by ' + gs.getUserDisplayName() + '.',
        finalDecision: 'close_requested',
    });
    current.update();

    var check = new GlideRecord(CASE_TABLE);
    if (check.get(caseId) && check.getValue('case_status') === 'closed') {
        gs.addInfoMessage('Case closed. The closure notification and metric snapshot have been triggered.');
    } else {
        gs.addErrorMessage(
            'The case could not be closed. Resolve the blocking items listed above (a resolution code, a resolution summary and completion of all mandatory tasks are required), then try again.'
        );
    }

    action.setRedirectURL(current);
})();
